128: void FrameConsole::DidFailLoading(DocumentLoader* loader,
129:                                   uint64_t request_identifier,
130:                                   const ResourceError& error) {
131:   // Report failures only.
132:   if (error.IsCancellation() || error.IsUnactionableTrustTokensStatus())
133:     return;
134: 
135:   if (error.WasBlockedByORB()) {
136:     // ORB loading errors are reported from the network service directly to
137:     // DevTools (CorsURLLoader::ReportOrbErrorToDevTools).
138:     return;
139:   }
140: 
141:   // Reduce noise in the DevTools console due to CORS policy errors.
142:   // See http://crbug.com/375357425.
143:   if (error.CorsErrorStatus() &&
144:       base::FeatureList::IsEnabled(features::kDevToolsImprovedNetworkError)) {
145:     return;
146:   }
147: 
148:   StringBuilder message;
149:   message.Append("Failed to load resource");
150:   if (!error.LocalizedDescription().empty()) {
151:     message.Append(": ");
152:     message.Append(error.LocalizedDescription());
153:   }
154:   auto* console_message = MakeGarbageCollected<ConsoleMessage>(
155:       mojom::blink::ConsoleMessageSource::kNetwork,
156:       mojom::blink::ConsoleMessageLevel::kError, message.ToString(),
157:       error.FailingURL(), loader, request_identifier);
158:   if (error.CorsErrorStatus()) {
159:     console_message->SetCategory(mojom::blink::ConsoleMessageCategory::Cors);
160:   }
161:   AddMessageToStorage(console_message);
162: }
